import {activeRefProof,nativePolicyResult} from './ref-reader.mjs';
import {riskOptions,projectDecision,policyCommitment,decisionCommitment,decisionInput} from './risk-policy.mjs';
import {composePolicy} from './decision-lab.mjs';
import {verifyCircuit} from './tapeout.mjs';
import {RISK_POLICY} from './risk-rules.mjs';
import {riskCircuitDraft,evaluateDraft} from './risk-circuit.mjs';
const panels=new Map(),esc=v=>String(v).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),money=n=>(n<0?'−':'')+'$'+Math.abs(n).toLocaleString('en-US',{maximumFractionDigits:0});
export function downloadJSON(value,name){const url=URL.createObjectURL(new Blob([JSON.stringify(value,null,2)],{type:'application/json'})),a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
export function mountRiskPanel(game,lang='vi',{container='#riskPreflight',source='local-game'}={}){const host=document.querySelector(container);if(!host)return;host.classList.add('decision-lab','risk-preflight');const options=riskOptions(game);host.hidden=!options.length;if(!options.length){const old=panels.get(host);if(old)old.key=null;return;}let p=panels.get(host);if(!p){p={host};panels.set(host,p);host.addEventListener('click',e=>{const key=e.target.closest('[data-risk]')?.dataset.risk;if(key==='verify')check(p);if(key==='download'&&p.evidence)downloadJSON(p.evidence,'moneylab-risk-evidence.json');if(key==='draft')downloadJSON(riskCircuitDraft(),'moneylab-risk-ref-design-NOT-DEPLOYED.json');});}const key=JSON.stringify([game.runId,game.month,game.phase,game.cash,game.reserve,game.positions,game.gate,game.pending?.eventId,game.labTrace?.actions?.length,lang,source]);if(p.key===key)return;p.key=key;p.state=structuredClone(game);p.lang=lang;p.source=source;p.evidence=null;p.projections=options.map(o=>projectDecision(p.state,o));draw(p);}
function draw(p){const vi=p.lang==='vi',t=(a,b)=>vi?a:b;const rows=p.projections.map(r=>{if(!r.feasible)return `<article class="risk-choice risk-blocked"><h3>${esc(r.option.label[p.lang])}</h3><b>${t('Không thực hiện được','Not executable')}: ${r.reason==='STOP'?'STOP':t('thiếu tiền sẵn có','insufficient available funds')}</b></article>`;const m=r.signals.model;return `<article class="risk-choice ${r.localOutput?'risk-pass':'risk-caution'}"><h3>${esc(r.option.label[p.lang])}</h3><p><b>${t('Tiền mặt còn lại','Cash left')}: ${money(r.after.cash)}</b><br>${t('Dự phòng','Reserve')}: ${money(r.after.reserve)} · ${t('Nợ','Debt')}: ${money(m.f.debt)}</p>${r.forecast?`<dl><div><dt>R · ${t('Dự phòng ≥ 1 tháng','Reserve ≥ 1 month')}</dt><dd>${r.signals.reserve?'✓':'!'} ${m.reserveMonths.toFixed(2)}</dd></div><div><dt>C · ${t('Còn sau nghĩa vụ tháng tới','After next known obligations')}</dt><dd>${r.signals.coverage?'✓':'!'} ${money(m.after)}</dd></div><div><dt>D · ${t('Trả góp ≤ 30% thu nhập','Installments ≤ 30% income')}</dt><dd>${r.signals.installments?'✓':'!'} ${money(m.installments)} / ${money(m.income)}</dd></div></dl><b>${r.localOutput?t('Đạt 3 tiêu chí minh họa','Meets 3 illustrative criteria'):t('Cần xem lại ít nhất một tiêu chí','At least one criterion needs attention')}</b>`:`<p>${t('Lựa chọn kết thúc chặng: không dự phóng tháng 13.','This choice ends the stage: no month-13 forecast.')}</p>`}</article>`;}).join('');p.host.innerHTML=`<p class="eyebrow">MONEY LAB × TAPEOUT · ${RISK_POLICY.id}</p><h2>${t('Kiểm tra trước khi quyết định','Check before you decide')}</h2><p>${t('Số tiền trên bàn cờ là USD giả lập, không phải HUB. So sánh vốn còn dùng được trước khi bấm chọn.','Board amounts are simulated USD, separate from HUB. Compare the money that remains available before choosing.')}</p><div class="lab-policy-grid">${rows}</div><p class="lab-fine">${t('Các số tiền và dấu kiểm trên đây do game tính, chưa phải bằng chứng đọc chain. Ngưỡng 1 tháng / 30% phục vụ học tập; đạt tiêu chí không bảo đảm có lãi. Cổng STOP hiện có vẫn khóa đầu tư mới.','Amounts and checks above are game calculations, not chain-read evidence yet. The 1-month / 30% thresholds are educational; passing does not guarantee profit. The existing STOP gate still blocks new investment.')}</p><button class="primary" data-risk="verify">${t('Đối chiếu quy tắc với TapeOut','Check the policy against TapeOut')}</button><details><summary>${t('Thiết kế tái sử dụng circuit','Reusable circuit design')}</summary><p>${t('Bản thiết kế gồm 4 REF tới mạch #48, ghép R AND C AND D. Tải file không tạo mạch hoặc ký ví; xem trang triển khai để biết trạng thái thực tế.','The design uses 4 REF records referencing circuit #48 to compose R AND C AND D. Downloading creates no circuit or wallet request; see the deployment page for live status.')}</p><p><a href="./ref-deploy.html">REF mainnet · status / deployment →</a></p><button class="secondary" data-risk="draft">${t('Tải thiết kế REF · chưa triển khai','Download REF design · not deployed')}</button><p><a href="./content/ref-atomic-simulation.json" target="_blank" rel="noopener">${t('Báo cáo bản sửa 2: 8/8 tổ hợp qua eth_call mô phỏng, chưa triển khai','Revision 2 report: 8/8 vectors in simulated eth_call, not deployed')}</a></p></details><div class="risk-proof" data-risk-proof role="status"></div>`;}
async function check(p){const key=p.key,host=p.host,t=(a,b)=>p.lang==='vi'?a:b,button=host.querySelector('[data-risk="verify"]'),target=host.querySelector('[data-risk-proof]');button.disabled=true;target.textContent=t('Đang đọc TapeOut mainnet, không ký ví…','Reading TapeOut mainnet, no wallet signature…');try{const proof=await verifyCircuit(),policyHash=await policyCommitment(),native=await activeRefProof('0x'+proof.blockNumber.toString(16));const branches=await Promise.all(p.projections.filter(r=>r.feasible&&r.forecast).map(async r=>({choice:r.option.choice,input:decisionInput(p.state,r.option),inputHash:await decisionCommitment(p.state,r.option),policyResult:composePolicy(r.signals,proof),nativeResult:native?nativePolicyResult(r.signals,native):null,projection:{cash:r.after.cash,reserve:r.after.reserve,nextKnownSurplus:r.signals.model.after,installments:r.signals.model.installments,income:r.signals.model.income}})));if(p.key!==key)return;const existingGate=proof.cases.find(r=>r.IN0===p.state.gate.IN0&&r.IN1===p.state.gate.IN1);if(!existingGate||existingGate.OUT0!==p.state.gate.OUT0)throw Error('GATE_MISMATCH');const vectors=Array.from({length:8},(_,n)=>{const inputs=[n&1,(n>>1)&1,(n>>2)&1],output=evaluateDraft(inputs,proof);if(output!==(inputs[0]&inputs[1]&inputs[2]))throw Error('REF_MISMATCH');return {inputs,output};});p.evidence={schema:'moneylab-risk-evidence.v1',source:p.source,runId:p.state.runId,month:p.state.month,policy:RISK_POLICY,policyHash,proof,nativeProof:native,existingGate,branches,draftConformance:{status:native?'DEPLOYED_AND_READ':'NOT_DEPLOYED',vectors},scope:native?'R/C/D combination is read from the deployed REF circuit. Financial comparison bits are calculated by Money Lab; this does not prove whole-game execution or safety.':'Offchain composition using actual TapeOut truth-table reads; the REF design is not activated. Money Lab supplies financial inputs.'};target.innerHTML=`<div class="lab-proof"><strong>${native?'REF #'+native.circuitId+' · ':''}${t('Đã đọc mạch #48 tại khối','Circuit #48 read at block')} ${proof.blockNumber}</strong>${native?`<p>${t('Phép ghép R/C/D được đọc trực tiếp từ circuit REF đã triển khai.','R/C/D combination is read directly from the deployed REF circuit.')}</p>`:''}<p>STOP gate: ${existingGate.IN0}, ${existingGate.IN1} → ${existingGate.OUT0}</p><p>${t('Các nhánh dùng chung bảng chân trị tại một khối. Thiết kế REF khớp cả 8 tổ hợp đầu vào trong kiểm tra cục bộ.','Branches share the same-block truth table. The REF design matches all 8 input combinations in the local check.')}</p><p>${t('Mã phiên bản quy tắc','Policy version')}: ${RISK_POLICY.id}<br>SHA-256: <code>${policyHash}</code></p>${branches.map(b=>`<details><summary>${esc(b.choice)} → ${b.nativeResult?.output??b.policyResult.output}</summary><ol>${b.policyResult.nodes.map(n=>`<li>${esc(n.name)}: ${n.IN0}, ${n.IN1} → ${n.OUT0}</li>`).join('')}</ol><code>${b.inputHash}</code></details>`).join('')}<p>${t('Dữ liệu tiền do Money Lab cung cấp; TapeOut không xác thực nguồn tiền hoặc toàn bộ ván.','Money Lab supplies financial inputs; TapeOut does not attest the money source or the whole game.')}</p><button class="secondary" data-risk="download">${t('Tải biên nhận quyết định JSON','Download decision receipt JSON')}</button></div>`;}catch{if(p.key===key){p.evidence=null;target.textContent=t('Chưa xác minh được. Không dùng kết quả cục bộ thay bằng chứng TapeOut. Anh có thể thử lại.','Verification unavailable. Local results do not replace TapeOut evidence. You can retry.');}}finally{if(p.key===key)button.disabled=false;}}
